content.content:
// Build/runtime environment for mode selection (see select.ts). No I/O.

export const DEFAULT_API_BASE = "http://localhost:8787";
export type SelectEnv = {
  PROD?: boolean;
  VITE_NOTARY_API?: string;
  VITE_NOTARY_LIVE?: string;
};

const buildEnv = (): SelectEnv => import.meta.env as unknown as SelectEnv;

/** Base URL of the local API: VITE_NOTARY_API, else the serve default. "" = same origin. */
export function resolveApiBase(env: SelectEnv = buildEnv()): string {
  const set = env.VITE_NOTARY_API;
  if (set === undefined) return DEFAULT_API_BASE;
  return String(set).trim().replace(/\/+$/, "");
}

/** The hosted/production build: replay only, never probes. */
export function isHostedBuild(env: SelectEnv = buildEnv()): boolean {
  return env.PROD === true && env.VITE_NOTARY_LIVE !== "1";
}

const LOOPBACK_HOSTS = new Set(["localhost", "127.0.0.1", "[::1]", "::1"]);

/**
 * Whether this page may probe the local API at all. Never on the hosted build. Otherwise only
 * from a loopback page (or a hostless context such as tests), unless VITE_NOTARY_API names the
 * API explicitly.
 */
export function shouldProbe(
  env: SelectEnv = buildEnv(),
  hostname: string | undefined = globalThis.location?.hostname,
): boolean {
  if (isHostedBuild(env)) return false;
  if (env.VITE_NOTARY_API !== undefined && env.VITE_NOTARY_API !== "") return true;
  if (!hostname) return true;
  return LOOPBACK_HOSTS.has(hostname) || hostname.endsWith(".localhost");
}
// The published files under packages/web/public/ — the ONLY module that knows their paths.
// ReplaySource reads everything from here; LiveSource reads fixture runs, fixture certificates
// and the precomputed explain answers from here (no API serves simulated data).
//
//   bundles/index.json, bundles/<runId>.json, bundles/<runId>.timeline.json      published runs
//   bundles/fixture/index.json, bundles/fixture/<runId>(.timeline).json            fixture runs (sample: true)
//   certificates/report.json, certificates/<tool>.json                              real certificates
//   certificates/fixture/index.json, certificates/fixture/<scenario>/…              fixture scenarios
//   content/explain.json, evidence/evidence.json, economics.json                    optional content
import { z } from "zod";
import {
  CertificateReportSchema,
  ExplainFileSchema,
  FixtureIndexSchema,
} from "../../../core/src/schema";
import type {
  BundleIndexEntry,
  ExplainFile,
  FixtureIndex,
  RunBundle,
  TimelineFile,
} from "../../../core/src/schema";
import { globalFetch, readJson, readOptionalJson, type FetchImpl } from "./http";
import { byNewest, chooseScenario, parseBundleIndex, validateBundle, verifyTimelineFile, verifyToolFile } from "./verify";
import type { CertificateWorld } from "./types";

/** Where a published run lives. */
export type RunDir = "bundles" | "bundles/fixture";
export type PublishedEntry = BundleIndexEntry & { dir: RunDir };

/** A certificate world plus the fixture scenario it came from and why it was chosen. */
export type CertificateWorldDetail = CertificateWorld & {
  scenario?: string;
  scenarioReason?: string;
};

/** Thrown when a run has no published (or served) timeline. The UI shows "not published", not an error. */
export class TimelineMissingError extends Error {
  constructor(readonly runId: string) {
    super(`No timeline is published for ${runId}.`);
    this.name = "TimelineMissingError";
  }
}

/** Human-readable names of the published files, for copy that tells people where data comes from. */
export const PUBLISHED_FILES = {
  evidence: "public/evidence/evidence.json",
  explain: "public/content/explain.json",
  economics: "public/economics.json",
  certificates: "public/certificates/",
  bundles: "public/bundles/",
} as const;

const baseUrl = (): string => String(import.meta.env.BASE_URL ?? "/");

/** URL of the published tool-evidence file (for a "download the receipts" link). */
export const evidenceFileUrl = (): string => `${baseUrl()}evidence/evidence.json`;

export const evidenceSchema = z.array(
  z.object({
    name: z.string(),
    purpose: z.string(),
    status: z.enum(["live", "pending"]),
    links: z.array(z.object({ label: z.string(), url: z.string() })),
    notes: z.string().optional(),
  }),
);
export type EvidenceEntry = z.infer<typeof evidenceSchema>[number];

export class PublishedFiles {
  private readonly base: string;
  private readonly fetchImpl: FetchImpl;
  /** runId → where it was listed, from the last catalog read. */
  private dirs = new Map<string, PublishedEntry>();
  /** Verified bundles keyed by dir/runId@contentHash (the index pins the hash). */
  private bundles = new Map<string, RunBundle>();

  constructor(opts: { base?: string; fetchImpl?: FetchImpl } = {}) {
    this.base = opts.base ?? baseUrl();
    this.fetchImpl = opts.fetchImpl ?? globalFetch;
  }

  private url(path: string) {
    return `${this.base}${path}`;
  }

  /** bundles/index.json (required). */
  async primaryIndex(signal?: AbortSignal): Promise<BundleIndexEntry[]> {
    const raw = await readJson(this.url("bundles/index.json"), "bundles/index.json", signal, this.fetchImpl);
    return [...parseBundleIndex(raw)].sort(byNewest);
  }

  /** bundles/fixture/index.json (optional); every entry must be `sample: true`. */
  async fixtureIndex(signal?: AbortSignal): Promise<BundleIndexEntry[]> {
    const response = await this.fetchImpl(this.url("bundles/fixture/index.json"), {
      signal,
      cache: "no-store",
    });
    if (response.headers.get("x-notary-hash-mismatch") === "1")
      throw new Error("Fixture index hash mismatch. Data withheld.");
    if (response.ok && response.headers.get("content-type")?.includes("json")) {
      let raw: unknown;
      try {
        raw = await response.json();
      } catch (e) {
        if ((e as Error).name === "AbortError") throw e;
        throw new Error("The fixture index is not valid JSON. Data withheld.");
      }
      let fixtures: BundleIndexEntry[];
      try {
        fixtures = parseBundleIndex(raw, "Fixture index");
      } catch {
        throw new Error("The fixture index does not match the shared Notary schema. Data withheld.");
      }
      if (fixtures.some((e) => !e.sample))
        throw new Error("Fixture directory contains a live bundle. Data withheld.");
      return fixtures;
    }
    if (!response.ok && response.status !== 404) throw new Error("Unable to load the fixture index.");
    return [];
  }

  /** Every published run (primary + fixture), newest first; run ids unique across both. */
  async catalog(signal?: AbortSignal): Promise<PublishedEntry[]> {
    const [primary, fixture] = await Promise.all([this.primaryIndex(signal), this.fixtureIndex(signal)]);
    const all: PublishedEntry[] = [
      ...primary.map((e) => ({ ...e, dir: "bundles" as const })),
      ...fixture.map((e) => ({ ...e, dir: "bundles/fixture" as const })),
    ];
    if (new Set(all.map((e) => e.runId)).size !== all.length)
      throw new Error("Duplicate run identifiers across bundle sources.");
    this.dirs = new Map(all.map((e) => [e.runId, e]));
    return all.sort(byNewest);
  }

  /** Published fixture runs only (LiveSource merges these next to the API's real runs). */
  async fixtureCatalog(signal?: AbortSignal): Promise<PublishedEntry[]> {
    const fixture = (await this.fixtureIndex(signal)).map((e) => ({ ...e, dir: "bundles/fixture" as const }));
    for (const e of fixture) this.dirs.set(e.runId, e);
    return fixture;
  }

  /** The index entry of a published run, reading the catalog if it has not been read yet. */
  async entry(runId: string, signal?: AbortSignal): Promise<PublishedEntry> {
    if (!this.dirs.has(runId)) await this.catalog(signal);
    const entry = this.dirs.get(runId);
    if (!entry) throw new Error(`Run ${runId} is not published.`);
    return entry;
  }

  /** Whether the last catalog read listed this run. */
  knows(runId: string): boolean {
    return this.dirs.has(runId);
  }

  /** A published bundle, schema-checked and hash-verified against its index entry. */
  async bundle(runId: string, signal?: AbortSignal): Promise<RunBundle> {
    const entry = await this.entry(runId, signal);
    const key = `${entry.dir}/${runId}@${entry.contentHash}`;
    const cached = this.bundles.get(key);
    if (cached) return cached;
    const path = `${entry.dir}/${encodeURIComponent(runId)}.json`;
    const { dir: _dir, ...indexEntry } = entry;
    const bundle = validateBundle(await readJson(this.url(path), path, signal, this.fetchImpl), indexEntry);
    this.bundles.set(key, bundle);
    return bundle;
  }

  /** The run's published timeline, tied to its verified bundle. TimelineMissingError when absent. */
  async timeline(runId: string, signal?: AbortSignal): Promise<TimelineFile> {
    const entry = await this.entry(runId, signal);
    const bundle = await this.bundle(runId, signal);
    const path = `${entry.dir}/${encodeURIComponent(runId)}.timeline.json`;
    const raw = await readOptionalJson(this.url(path), path, signal, this.fetchImpl);
    if (raw === undefined) throw new TimelineMissingError(runId);
    return verifyTimelineFile(raw, bundle);
  }

  /** certificates/fixture/index.json, validated; null when not published. */
  async fixtureCertificateIndex(signal?: AbortSignal): Promise<FixtureIndex | null> {
    const raw = await readOptionalJson(
      this.url("certificates/fixture/index.json"),
      "certificates/fixture/index.json",
      signal,
      this.fetchImpl,
    );
    if (raw === undefined) return null;
    const index = FixtureIndexSchema.safeParse(raw);
    if (!index.success)
      throw new Error("The fixture certificate index does not match the shared schema. Data withheld.");
    return index.data;
  }

  /**
   * Real certificates (sample false) or the fixture scenario for `runId` (sample true). Every file
   * is schema-checked, pinned by its report's hash, and every record's seal recomputed.
   * `report: null` = nothing published for that world.
   */
  async certificateWorld(sample: boolean, runId?: string, signal?: AbortSignal): Promise<CertificateWorldDetail> {
    let base = "certificates/";
    let scenario: string | undefined;
    let scenarioReason: string | undefined;
    if (sample) {
      const index = await this.fixtureCertificateIndex(signal);
      const chosen = index ? chooseScenario(index, runId) : undefined;
      // "fixture:none": no fixture certificate export is published; report null says so.
      if (!chosen) return { world: "fixture:none", sample: true, tools: [], report: null };
      scenario = chosen.scenario.scenario;
      scenarioReason = chosen.reason;
      const reportPath = chosen.scenario.report;
      base = `certificates/fixture/${reportPath.slice(0, reportPath.lastIndexOf("/") + 1)}`;
    }
    const world: CertificateWorld["world"] = sample ? `fixture:${scenario}` : "real";
    const rawReport = await readOptionalJson(this.url(`${base}report.json`), `${base}report.json`, signal, this.fetchImpl);
    if (rawReport === undefined) return { world, sample, tools: [], report: null, scenario, scenarioReason };
    const parsed = CertificateReportSchema.safeParse(rawReport);
    if (!parsed.success)
      throw new Error("The certificate report does not match the shared schema. Data withheld.");
    const report = parsed.data;
    if (report.sample !== sample || report.scenario !== scenario)
      throw new Error("The certificate report belongs to a different data world. Data withheld.");
    const tools = await Promise.all(
      report.tools.map(async (entry) => {
        const path = `${base}${entry.file}`;
        const raw = await readOptionalJson(this.url(path), path, signal, this.fetchImpl);
        if (raw === undefined) throw new Error(`${entry.file} is listed in the report but missing.`);
        return verifyToolFile(raw, report.toolFileHashes[entry.file], sample, entry.file);
      }),
    );
    return { world, sample, tools, report, scenario, scenarioReason };
  }

  /** content/explain.json, validated; null when not published. */
  async explain(signal?: AbortSignal): Promise<ExplainFile | null> {
    const raw = await readOptionalJson(this.url("content/explain.json"), "content/explain.json", signal, this.fetchImpl);
    if (raw === undefined) return null;
    const parsed = ExplainFileSchema.safeParse(raw);
    if (!parsed.success) throw new Error("explain.json does not match the shared schema. Answers withheld.");
    return parsed.data;
  }

  /** evidence/evidence.json (tool integration receipts); [] when not published. */
  async evidence(signal?: AbortSignal): Promise<EvidenceEntry[]> {
    const r = await this.fetchImpl(this.url("evidence/evidence.json"), { signal, cache: "no-store" });
    if (r.status === 404 || (r.ok && !r.headers.get("content-type")?.includes("json"))) return [];
    if (!r.ok) throw new Error("Tool evidence could not be loaded.");
    let raw: unknown;
    try {
      raw = await r.json();
    } catch (e) {
      if ((e as Error).name === "AbortError") throw e;
      throw new Error("evidence/evidence.json is not valid JSON. Data withheld.");
    }
    const parsed = evidenceSchema.safeParse(raw);
    if (!parsed.success)
      throw new Error("evidence/evidence.json does not match the evidence schema. Data withheld.");
    return parsed.data;
  }

  /** economics.json (the cfo.ai plan), raw; undefined when not published. */
  async economics(signal?: AbortSignal): Promise<unknown | undefined> {
    return readOptionalJson(this.url("economics.json"), "economics.json", signal, this.fetchImpl);
  }
}
// Trust checks run in the browser before anything renders: shared-schema validation, bundle
// content hashes, timeline ↔ bundle hash ties, certificate seals and report pins. Pure functions
// (no I/O), shared by LiveSource and ReplaySource. Moved from src/data.ts and state/certificates.ts.
import { BundleIndexSchema, RunBundleSchema } from "../../../core/src/schema/bundle";
import { ToolCertificatesSchema, TimelineFileSchema } from "../../../core/src/schema";
import type {
  BundleIndexEntry,
  FixtureIndex,
  RunBundle,
  TimelineFile,
  ToolCertificates,
} from "../../../core/src/schema";
import { canonicalJson, computeContentHash, sha256Hex } from "../../../core/src/bundle/hash";

/** Schema + content hash (+ agreement with its index entry). Throws, data withheld, otherwise. */
export function validateBundle(raw: unknown, entry?: BundleIndexEntry): RunBundle {
  const parsed = RunBundleSchema.safeParse(raw);
  if (!parsed.success)
    throw new Error("Bundle does not match the shared Notary schema. Data withheld.");
  const bundle = parsed.data;
  if (computeContentHash(bundle) !== bundle.contentHash)
    throw new Error(`Content hash mismatch for ${bundle.runId}. Data withheld.`);
  if (
    entry &&
    (entry.runId !== bundle.runId ||
      entry.contentHash !== bundle.contentHash ||
      entry.sample !== bundle.sample ||
      entry.kind !== bundle.kind ||
      entry.variant !== bundle.variant ||
      entry.mode !== bundle.mode ||
      entry.status !== bundle.status ||
      entry.startedAt !== bundle.startedAt)
  )
    throw new Error("Bundle disagrees with its index entry. Data withheld.");
  return bundle;
}

/** A bundle index (array of entries), schema-checked, run ids unique. */
export function parseBundleIndex(raw: unknown, what = "Bundle index"): BundleIndexEntry[] {
  const parsed = BundleIndexSchema.safeParse(raw);
  if (!parsed.success) throw new Error(`${what} does not match the shared Notary schema.`);
  if (new Set(parsed.data.map((e) => e.runId)).size !== parsed.data.length)
    throw new Error(`Duplicate run identifiers in ${what.toLowerCase()}.`);
  return parsed.data;
}

export const byNewest = <T extends { startedAt: string }>(a: T, b: T) =>
  b.startedAt.localeCompare(a.startedAt);

/**
 * Parse a timeline file and tie it to its verified bundle: same run, same sample flag, the
 * bundle's content hash, events of this run with strictly increasing seq. Throws otherwise.
 */
export function verifyTimelineFile(raw: unknown, bundle: RunBundle): TimelineFile {
  const parsed = TimelineFileSchema.safeParse(raw);
  if (!parsed.success)
    throw new Error(
      `The timeline for ${bundle.runId} does not match the shared timeline schema. Data withheld.`,
    );
  const file = parsed.data;
  if (file.runId !== bundle.runId)
    throw new Error(`The timeline is for run ${file.runId}, not ${bundle.runId}. Data withheld.`);
  if (file.sample !== bundle.sample)
    throw new Error(
      `The timeline's sample flag (${file.sample}) disagrees with the bundle (${bundle.sample}). Data withheld.`,
    );
  if (file.bundleHash !== bundle.contentHash)
    throw new Error(
      `Timeline hash mismatch for ${bundle.runId}: it belongs to bundle ${file.bundleHash.slice(0, 12)}…, not the verified bundle ${bundle.contentHash.slice(0, 12)}…. Data withheld.`,
    );
  file.events.forEach((e, i) => {
    if (e.runId !== bundle.runId || (i > 0 && e.seq <= file.events[i - 1]!.seq))
      throw new Error(`The timeline for ${bundle.runId} is out of order. Data withheld.`);
  });
  return file;
}

// ---------------------------------------------------------------------------- certificates

/** sha256 of a certificate/revocation record without its own sha256 field. */
export const sealOf = (record: { sha256: string }) => {
  const { sha256: _ignored, ...rest } = record;
  return sha256Hex(canonicalJson(rest));
};

/** Every record's seal and sample flag. Throws (data withheld) on the first failure. */
export function verifyToolRecords(tool: ToolCertificates, sample: boolean, file: string): ToolCertificates {
  if (tool.sample !== sample)
    throw new Error(`${file} mixes fixture and real certificate data. Data withheld.`);
  for (const record of [...tool.certificates, ...tool.revocations]) {
    if (sealOf(record) !== record.sha256)
      throw new Error(`Seal mismatch for ${record.id}. Data withheld.`);
    if (record.sample !== sample)
      throw new Error(`${record.id} mixes fixture and real data. Data withheld.`);
  }
  return tool;
}

/** Throws (data withheld) when a tool file, its report pin, or any record inside it fails. */
export function verifyToolFile(
  raw: unknown,
  expectedHash: string | undefined,
  sample: boolean,
  file: string,
): ToolCertificates {
  const parsed = ToolCertificatesSchema.safeParse(raw);
  if (!parsed.success)
    throw new Error(`${file} does not match the shared certificate schema. Data withheld.`);
  if (expectedHash === undefined || sha256Hex(canonicalJson(raw)) !== expectedHash)
    throw new Error(`${file} does not match the hash pinned in its report. Data withheld.`);
  return verifyToolRecords(parsed.data, sample, file);
}

/** Runs whose ids differ only in their trailing kind/variant share a key ("demo-change-api"). */
export const scenarioKey = (runId: string) => runId.replace(/-(run|notarize)-[a-z]+$/, "");

/**
 * Pick the fixture scenario for a run: the scenario that lists the run as a source bundle, else
 * the scenario whose source bundles belong to the same simulated world (same scenarioKey, e.g.
 * a queue run next to its notarize runs). Never another world: no match → undefined (the UI says
 * no certificates were published for this run's world). Returns the reason shown on screen.
 */
export function chooseScenario(
  index: FixtureIndex,
  runId: string | undefined,
): { scenario: FixtureIndex["scenarios"][number]; reason: string } | undefined {
  if (!runId) return undefined;
  const listed = index.scenarios.find((s) => s.sourceBundles.includes(runId));
  if (listed)
    return {
      scenario: listed,
      reason: `${runId} is a source bundle of fixture scenario "${listed.scenario}".`,
    };
  const key = scenarioKey(runId);
  const sameWorld = index.scenarios.find((s) => s.sourceBundles.some((b) => scenarioKey(b) === key));
  return sameWorld
    ? {
        scenario: sameWorld,
        reason: `${runId} belongs to the same simulated world as fixture scenario "${sameWorld.scenario}" (its notarize runs are the certificate sources).`,
      }
    : undefined;
}

// ------------------------------------------------------------------------------- approvals

/** The id `notary serve` gives a held decision: "appr-" + sha256(runId \n decisionId)[:16]. */
export const approvalId = (runId: string, decisionId: string) =>
  `appr-${sha256Hex(`${runId}\n${decisionId}`).slice(0, 16)}`;
// Mode selection. LiveSource iff the API at VITE_NOTARY_API (default http://localhost:8787, the
// `notary serve` default port) answers GET /api/health with a schema-valid HealthResponse;
// otherwise ReplaySource. No global mode banner (K4): pages say "Start the server…" where a live
// action fails, and fixture runs keep their fixture note.
//
// The hosted (production) build is ALWAYS replay and never probes anything: `notary serve`
// accepts loopback requests only (DECISIONS #115), so a hosted page could never reach it and a
// probe would only log console errors (#133). A production build meant for local use can opt in
// with VITE_NOTARY_LIVE=1 at build time. In dev, a page served from a non-loopback host only
// probes when VITE_NOTARY_API is set explicitly. VITE_NOTARY_API="" (or "/") means same origin,
// i.e. the Vite dev proxy forwarding /api to 127.0.0.1:8787.
import { HealthResponseSchema, type HealthResponse } from "../../../core/src/schema";
import { globalFetch, type FetchImpl } from "./http";
import { LiveSource, type EventSourceCtor } from "./live";
import { PublishedFiles } from "./published";
import { ReplaySource } from "./replay";
import type { DataMode, DataSource } from "./types";
import { isHostedBuild, resolveApiBase, shouldProbe, type SelectEnv } from "./env";

export { DEFAULT_API_BASE, isHostedBuild, resolveApiBase, shouldProbe, type SelectEnv } from "./env";

export const HEALTH_TIMEOUT_MS = 1500;

export type HealthProbe =
  | { ok: true; health: HealthResponse }
  /** Nothing answered (refused, timeout, non-JSON, non-2xx). Quietly replay. */
  | { ok: false; reason: "unreachable" }
  /** Something answered with JSON that is not a HealthResponse: replay, and say why. */
  | { ok: false; reason: "invalid"; error: string };

/** GET <base>/api/health, validated with HealthResponseSchema. Never throws. */
export async function probeHealth(
  base: string,
  opts: { fetchImpl?: FetchImpl; timeoutMs?: number; signal?: AbortSignal } = {},
): Promise<HealthProbe> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), opts.timeoutMs ?? HEALTH_TIMEOUT_MS);
  const forward = () => controller.abort();
  opts.signal?.addEventListener("abort", forward, { once: true });
  let raw: unknown;
  try {
    const response = await (opts.fetchImpl ?? globalFetch)(`${base}/api/health`, {
      signal: controller.signal,
      cache: "no-store",
      headers: { accept: "application/json" },
    });
    if (!response.ok || !response.headers.get("content-type")?.includes("json"))
      return { ok: false, reason: "unreachable" };
    raw = await response.json();
  } catch {
    return { ok: false, reason: "unreachable" };
  } finally {
    clearTimeout(timer);
    opts.signal?.removeEventListener("abort", forward);
  }
  const parsed = HealthResponseSchema.safeParse(raw);
  return parsed.success
    ? { ok: true, health: parsed.data }
    : {
        ok: false,
        reason: "invalid",
        error: `The API at ${base || "this origin"} answered /api/health with something that is not a Notary health response, so this page is replaying published files.`,
      };
}

export type Selection = {
  source: DataSource;
  mode: DataMode;
  /** Live: the probe's health response. Replay: null. */
  health: HealthResponse | null;
  /** True on the hosted build (always replay, never probed). */
  hosted: boolean;
  apiBase: string;
  /** Why live mode was refused although something answered; null otherwise. */
  error: string | null;
};

export type SelectOptions = {
  env?: SelectEnv;
  hostname?: string;
  fetchImpl?: FetchImpl;
  EventSourceImpl?: EventSourceCtor;
  published?: PublishedFiles;
  timeoutMs?: number;
  signal?: AbortSignal;
};

/** The replay selection, known synchronously (used before/without a probe). */
export function replaySelection(opts: SelectOptions = {}): Selection {
  const env = opts.env ?? (import.meta.env as unknown as SelectEnv);
  return {
    source: new ReplaySource({ published: opts.published ?? new PublishedFiles({ fetchImpl: opts.fetchImpl }) }),
    mode: "replay",
    health: null,
    hosted: isHostedBuild(env),
    apiBase: resolveApiBase(env),
    error: null,
  };
}

/** Probe (when allowed) and pick the data source. Never throws. */
export async function selectDataSource(opts: SelectOptions = {}): Promise<Selection> {
  const env = opts.env ?? (import.meta.env as unknown as SelectEnv);
  const replay = replaySelection(opts);
  if (!shouldProbe(env, "hostname" in opts ? opts.hostname : globalThis.location?.hostname)) return replay;
  const base = resolveApiBase(env);
  const probe = await probeHealth(base, { fetchImpl: opts.fetchImpl, timeoutMs: opts.timeoutMs, signal: opts.signal });
  if (!probe.ok) return { ...replay, error: probe.reason === "invalid" ? probe.error : null };
  const published = opts.published ?? new PublishedFiles({ fetchImpl: opts.fetchImpl });
  return {
    source: new LiveSource({ base, fetchImpl: opts.fetchImpl, EventSourceImpl: opts.EventSourceImpl, published }),
    mode: "live",
    health: probe.health,
    hosted: false,
    apiBase: base,
    error: null,
  };
}

// ReplaySource: the published files under public/ (bundles, timelines, certificates, explain).
// Every bundle is hash-verified, every timeline is tied to its bundle's hash, every certificate
// seal is recomputed. Nothing live is invented: health is null, approvals are the held decisions
// of the recorded runs (read-only, testMode false, no amounts — only the server computes those),
// and every live-only operation throws ReplayOnlyError.
import type {
  ApprovalRecord,
  ApprovalsList,
  AskResponse,
  ExplainFile,
  PendingApproval,
  RunBundle,
  StartRunResponse,
  TimelineEvent,
} from "../../../core/src/schema";
import { PublishedFiles, type CertificateWorldDetail } from "./published";
import { realTimers, replayStream, type Timers } from "./stream";
import { approvalId } from "./verify";
import type { ReplayChat, ReplayChatData, ReplayChatOptions } from "./chat-replay";
import type { ChatConversation, ChatEvent, ConversationDetail } from "../../../core/src/schema";
import { ReplayOnlyError, type ChatSource, type DataSource, type EventStreamOptions, type RunEntry } from "./types";

/**
 * The replay chat engine (chat-replay.ts, ~900 lines with its router and store) loads on first use,
 * so the landing (`/`), which builds a ReplaySource at startup, never downloads it up front (K4).
 * Same ChatSource contract: setContext is synchronous, and every call applies the context that was
 * current when it was made, so `setContext → createConversation → setContext → sendMessage` pins
 * worlds exactly as on the engine itself.
 */
class LazyReplayChat implements ChatSource {
  private engine: Promise<ReplayChat> | undefined;
  private ctx: { runId?: string } = {};

  constructor(
    private readonly data: ReplayChatData,
    private readonly opts: ReplayChatOptions,
  ) {}

  private async load(): Promise<ReplayChat> {
    const ctx = this.ctx;
    this.engine ??= import("./chat-replay").then((m) => new m.ReplayChat(this.data, this.opts));
    this.engine.catch(() => (this.engine = undefined));
    const engine = await this.engine;
    engine.setContext(ctx);
    return engine;
  }

  setContext(ctx: { runId?: string }): void {
    this.ctx = { ...ctx };
  }

  async listConversations(): Promise<ChatConversation[]> {
    return (await this.load()).listConversations();
  }

  async getConversation(id: string): Promise<ConversationDetail> {
    return (await this.load()).getConversation(id);
  }

  async createConversation(): Promise<ChatConversation> {
    return (await this.load()).createConversation();
  }

  async deleteConversation(id: string): Promise<void> {
    return (await this.load()).deleteConversation(id);
  }

  async conversationWorld(id: string): ReturnType<ReplayChat["conversationWorld"]> {
    return (await this.load()).conversationWorld(id);
  }

  async sendMessage(conversationId: string, content: string, onEvent: (e: ChatEvent) => void, signal?: AbortSignal): Promise<void> {
    return (await this.load()).sendMessage(conversationId, content, onEvent, signal);
  }
}

export class ReplaySource implements DataSource {
  readonly mode = "replay" as const;
  readonly published: PublishedFiles;
  private readonly timers: Timers;
  /** The deterministic replay chat engine over these files (no backend, no model), loaded on first use. */
  readonly chat: LazyReplayChat;

  constructor(opts: { published?: PublishedFiles; timers?: Timers; chat?: ReplayChatOptions } = {}) {
    this.published = opts.published ?? new PublishedFiles();
    this.timers = opts.timers ?? realTimers;
    this.chat = new LazyReplayChat(this, { timers: this.timers, ...opts.chat });
  }

  async health(): Promise<null> {
    return null;
  }

  async listRuns(signal?: AbortSignal): Promise<RunEntry[]> {
    return (await this.published.catalog(signal)).map(({ dir: _dir, ...e }) => ({ ...e, state: "finished" as const }));
  }

  getRun(runId: string, signal?: AbortSignal): Promise<RunBundle> {
    return this.published.bundle(runId, signal);
  }

  async getTimeline(runId: string, signal?: AbortSignal): Promise<TimelineEvent[]> {
    return (await this.published.timeline(runId, signal)).events;
  }

  /** The recorded timeline at opts.speed (1×, 4× or instant; default 1×). */
  streamEvents(runId: string, onEvent: (e: TimelineEvent) => void, opts: EventStreamOptions = {}): () => void {
    return replayStream(() => this.getTimeline(runId), onEvent, opts, this.timers);
  }

  certificates(forRun?: RunEntry, signal?: AbortSignal): Promise<CertificateWorldDetail> {
    const sample = forRun?.state === "finished" && forRun.sample;
    return this.published.certificateWorld(sample, forRun?.runId, signal);
  }

  /**
   * Held decisions of every published run, as recorded. Read-only: testMode false, no `amount`
   * (the held amount is computed by `notary serve`, never guessed here) and no decided records
   * (no approvals file is published). Items of fixture runs are included; their run entry says
   * `sample: true` — group by it, never mix them with real runs.
   */
  async approvals(signal?: AbortSignal): Promise<ApprovalsList> {
    const runs = await this.listRuns(signal);
    const bundles = await Promise.all(runs.map((r) => this.getRun(r.runId, signal)));
    const pending: PendingApproval[] = bundles.flatMap((b) =>
      b.decisions
        .filter((d) => d.status === "held")
        .map((d) => ({
          id: approvalId(b.runId, d.id),
          runId: b.runId,
          decisionId: d.id,
          requestId: d.requestId,
          action: d.action,
          // Same rule the server uses for a pending item's reason.
          reason: d.error ?? d.evidencePack?.reason ?? "held",
          missingBeliefs: d.missingBeliefs,
        })),
    );
    return { testMode: false, pending, decided: [] };
  }

  explain(signal?: AbortSignal): Promise<ExplainFile | null> {
    return this.published.explain(signal);
  }

  async startRun(): Promise<StartRunResponse> {
    throw new ReplayOnlyError("Starting a run");
  }

  async approve(): Promise<ApprovalRecord> {
    throw new ReplayOnlyError("Approving a held action");
  }

  async reject(): Promise<ApprovalRecord> {
    throw new ReplayOnlyError("Rejecting a held action");
  }

  async ask(): Promise<AskResponse> {
    throw new ReplayOnlyError("Asking a free-form question");
  }
}
// Redesign R1 contract: the ONE data layer every component goes through.
//
//   LiveSource   — talks to a local `notary serve` (REST + SSE), schemas in core/src/schema/api.ts
//   ReplaySource — reads exported bundles / timelines / certificates from public/
//
// No file outside src/data/ may fetch public/bundles, public/certificates, public/content or any
// fixture path directly (enforced by test/data-boundary.test.ts). Every bundle is hash-verified in
// the browser before it is returned. Replay never invents live-only data: live-only operations
// throw ReplayOnlyError with a user-facing message.
import type {
  ApprovalRecord,
  ApprovalsList,
  AskRequest,
  AskResponse,
  BundleIndexEntry,
  ChatConversation,
  ChatEvent,
  ConversationDetail,
  CertificateReport,
  ExplainFile,
  HealthResponse,
  RunBundle,
  StartRunRequest,
  StartRunResponse,
  TimelineEvent,
  ToolCertificates,
} from "../../../core/src/schema";

export type DataMode = "live" | "replay";

/** One run as the run selector lists it. `sample: true` = fixture (simulated APIs) — always labelled. */
export type RunEntry =
  | (BundleIndexEntry & { state: "finished" })
  | { runId: string; state: "running"; kind: "run" | "notarize"; startedAt: string };

/** Certificates of one data world (real runs, or one fixture scenario). Never mixed. */
export type CertificateWorld = {
  world: "real" | `fixture:${string}`;
  sample: boolean;
  tools: ToolCertificates[];
  report: CertificateReport | null;
};

export type EventStreamOptions = {
  /** Replay only: events per real second multiplier; "instant" emits everything at once. Live ignores it. */
  speed?: 1 | 4 | "instant";
  /** Called once when the stream has delivered run.finished (or the recorded file ended). */
  onEnd?: () => void;
  onError?: (message: string) => void;
};

export interface DataSource {
  readonly mode: DataMode;
  /** Live: GET /api/health. Replay: null (the UI says the hosted/replay build has no live integrations). */
  health(signal?: AbortSignal): Promise<HealthResponse | null>;
  listRuns(signal?: AbortSignal): Promise<RunEntry[]>;
  /** Hash-verified bundle; throws on mismatch (the UI shows the error, never the data). */
  getRun(runId: string, signal?: AbortSignal): Promise<RunBundle>;
  /** Recorded events (timeline.jsonl / published timeline), validated and hash-tied to the bundle. */
  getTimeline(runId: string, signal?: AbortSignal): Promise<TimelineEvent[]>;
  /** Live: SSE /api/runs/:id/events. Replay: the recorded timeline at `speed`. Returns unsubscribe. */
  streamEvents(runId: string, onEvent: (e: TimelineEvent) => void, opts?: EventStreamOptions): () => void;
  /** Certificates for the world of the given run (real runs → real certificates; fixture → its scenario). */
  certificates(forRun?: RunEntry, signal?: AbortSignal): Promise<CertificateWorld>;
  /** Live: GET /api/approvals. Replay: held decisions of recorded runs, read-only (testMode false). */
  approvals(signal?: AbortSignal): Promise<ApprovalsList>;
  /** Precomputed explain answers (public/content/explain.json), or null if not published. */
  explain(signal?: AbortSignal): Promise<ExplainFile | null>;
  // ---- live only (ReplaySource throws ReplayOnlyError) ----
  startRun(req: StartRunRequest): Promise<StartRunResponse>;
  approve(id: string, confirmedAmount: number): Promise<ApprovalRecord>;
  reject(id: string, reason: string): Promise<ApprovalRecord>;
  ask(req: AskRequest): Promise<AskResponse>;
  /** Notary Chat (C1–C3). Live: /api/chat (sqlite on the server, real tools). Replay: the same event
   *  shapes from a deterministic engine over the exported bundles (sessionStorage conversations;
   *  fetch_doc / crustdata_lookup / dodo_lookup emit step_finished status "unavailable"). */
  readonly chat: ChatSource;
}

export interface ChatSource {
  listConversations(signal?: AbortSignal): Promise<ChatConversation[]>;
  getConversation(id: string, signal?: AbortSignal): Promise<ConversationDetail>;
  createConversation(): Promise<ChatConversation>;
  deleteConversation(id: string): Promise<void>;
  /** Streams ChatEvents in order until `done` or `error`; aborting `signal` is the Stop button. */
  sendMessage(conversationId: string, content: string, onEvent: (e: ChatEvent) => void, signal?: AbortSignal): Promise<void>;
  /** Replay only: the run selected in the dashboard. A new replay conversation is pinned to that
   *  run's world (worlds never mix). Live ignores it (`notary serve` serves real runs only). */
  setContext?(ctx: { runId?: string }): void;
}

/** Shown on the Chat page in replay mode. */
export const REPLAY_CHAT_BANNER = "Replay — answers come from the recorded run, no live lookups";

export class ReplayOnlyError extends Error {
  constructor(action: string) {
    super(`${action} needs live mode — start \`pnpm notary serve\` and reload.`);
    this.name = "ReplayOnlyError";
  }
}

/** Shown whenever the data on screen came from sample: true bundles (simulated APIs). */
export const FIXTURE_BANNER = "Fixture data — simulated APIs, not a live run";
// Data worlds (moved from the old Ask model). Mirrors packages/core/src/explain/world.ts
// `worldKeyOf` (web may not import it): "real" for sample:false, "synthetic" for the dashboard's
// SAMPLE bundle, else "fixture:<scenario>" from the "(fixture scenario <name>)" disclosure; none =
// "default". Worlds never mix: not in a chart, a table, an answer or a chat turn.
import type { ExplainAnswer, RunBundle } from "../../../core/src/schema";

export type WorldKey = string;
export type WorldFields = Pick<RunBundle, "sample" | "kind" | "variant" | "disclosure">;

const SCENARIO_RE = /\(fixture scenario ([A-Za-z0-9_-]+)\)/;

export function worldKeyOf(b: WorldFields): WorldKey {
  if (!b.sample) return "real";
  if (b.kind === "sample" || b.variant === "sample") return "synthetic";
  for (const d of b.disclosure) {
    const m = SCENARIO_RE.exec(d);
    if (m) return `fixture:${m[1]}`;
  }
  return "fixture:default";
}

export function worldLabel(key: WorldKey): string {
  if (key === "real") return "real runs";
  if (key === "synthetic") return "synthetic sample data";
  if (key.startsWith("fixture:")) return `fixture scenario ${key.slice("fixture:".length)} (simulated APIs)`;
  return key;
}

/** runId -> world key for every verified bundle. */
export function worldIndex(bundles: readonly (WorldFields & { runId: string })[]): Map<string, WorldKey> {
  return new Map(bundles.map((b) => [b.runId, worldKeyOf(b)]));
}

/**
 * The one world an explain answer belongs to, from the bundles its runIds name. Undefined when a run
 * is unknown, the runs span worlds, or the answer's `sample` flag disagrees: such an answer is never
 * used (a world we can't prove is a world we might mix).
 */
export function answerWorld(
  answer: Pick<ExplainAnswer, "runIds" | "sample">,
  worlds: Map<string, WorldKey>,
): WorldKey | undefined {
  if (!answer.runIds.length) return undefined;
  const keys = new Set(answer.runIds.map((id) => worlds.get(id)));
  if (keys.size !== 1) return undefined;
  const [key] = keys;
  if (key === undefined) return undefined;
  if ((key !== "real") !== answer.sample) return undefined;
  return key;
}
// Published incidents (public/incidents/index.json for real runs and public/incidents/fixture/index.json
// for fixture runs, IncidentsIndex files written by `notary export` / `publish:incidents`) and the bundle
// indexes they are tied to. Incidents never live inside public/bundles. Like published.ts, this module is the only place that
// knows the file paths; it only reads and validates. What the page shows is derived in
// pages/incidents/model.ts.
import { IncidentsIndexSchema } from "../../../core/src/schema";
import type { BundleIndexEntry, IncidentsIndex } from "../../../core/src/schema";
import { globalFetch, readOptionalJson, type FetchImpl } from "./http";
import { parseBundleIndex } from "./verify";

export const INCIDENTS_FILE = "public/incidents/index.json";
export const FIXTURE_INCIDENTS_FILE = "public/incidents/fixture/index.json";

/** A bundle index as read for the hash tie-in: entries, or why they could not be read. */
export type IndexRead = { entries: BundleIndexEntry[] } | { entries: null; error?: string };

export type IncidentsLoad =
  /** No incidents file is published (404 / SPA fallback). */
  | { status: "missing" }
  | {
      status: "ready";
      index: IncidentsIndex;
      /** bundles/index.json (real runs; may also list sample runs). */
      primary: IndexRead;
      /** bundles/fixture/index.json (fixture runs). */
      fixture: IndexRead;
    };

const baseUrl = (): string => String(import.meta.env.BASE_URL ?? "/");

async function readIndex(url: string, label: string, signal: AbortSignal | undefined, fetchImpl: FetchImpl): Promise<IndexRead> {
  let raw: unknown;
  try {
    raw = await readOptionalJson(url, label, signal, fetchImpl);
  } catch (e) {
    if ((e as Error).name === "AbortError") throw e;
    return { entries: null, error: (e as Error).message };
  }
  if (raw === undefined) return { entries: null };
  try {
    return { entries: parseBundleIndex(raw, label) };
  } catch (e) {
    return { entries: null, error: (e as Error).message };
  }
}

/**
 * Read and validate the published incidents. `missing` when nothing is published; throws (with a
 * plain-language message) when the file is unreadable or does not match IncidentsIndexSchema.
 * The bundle indexes are read alongside so each run can be checked against its published bundle.
 */
export async function loadIncidents(
  opts: { signal?: AbortSignal; fetchImpl?: FetchImpl; base?: string } = {},
): Promise<IncidentsLoad> {
  const base = opts.base ?? baseUrl();
  const fetchImpl = opts.fetchImpl ?? globalFetch;
  const [rawReal, rawFixture] = await Promise.all([
    readOptionalJson(`${base}incidents/index.json`, "incidents/index.json", opts.signal, fetchImpl),
    readOptionalJson(`${base}incidents/fixture/index.json`, "incidents/fixture/index.json", opts.signal, fetchImpl),
  ]);
  if (rawReal === undefined && rawFixture === undefined) return { status: "missing" };
  const parse = (raw: unknown, label: string): IncidentsIndex["runs"] => {
    if (raw === undefined) return [];
    const parsed = IncidentsIndexSchema.safeParse(raw);
    if (!parsed.success) throw new Error(`${label} does not match the shared Notary schema. Incidents withheld.`);
    // Each run keeps its own sample flag; a fixture index marks all of its runs as fixture.
    return parsed.data.runs.map((r) => (parsed.data.sample ? { ...r, sample: true } : r));
  };
  const runs = [...parse(rawReal, "incidents/index.json"), ...parse(rawFixture, "incidents/fixture/index.json")];
  const parsed = { data: { sample: false, runs } as IncidentsIndex };
  const [primary, fixture] = await Promise.all([
    readIndex(`${base}bundles/index.json`, "Bundle index", opts.signal, fetchImpl),
    readIndex(`${base}bundles/fixture/index.json`, "Fixture index", opts.signal, fetchImpl),
  ]);
  return { status: "ready", index: parsed.data, primary, fixture };
}

// One provider for the dashboard's data world, read through the data layer (src/data): the run
// list of the selected DataSource (live `notary serve` or replay of published files), every
// hash-verified bundle, the selected run (from ?run=), its same-cohort baseline
// (?baseline=), the certificate world matching the selected run, and the tool evidence file.
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import { useSearchParams } from "react-router";
import type { BundleIndexEntry, RunBundle } from "../../../core/src/schema";
import {
  byNewest,
  entryOfBundle,
  finishedEntries,
  loadEvidence,
  toCertificateView,
  useDataSource,
  type CatalogOrigin,
  type CertificateView,
  type DataSource,
  type EvidenceEntry,
  type RunEntry,
} from "../data";
import {
  baselineCandidates,
  defaultRunId,
  fixturesRequested,
  groupRuns,
  pickBaseline,
  resolveDataMode,
  visibleRuns,
  type DataMode,
  type RunGroup,
} from "./links";

export type { EvidenceEntry };

export type Loadable<T> =
  | { status: "loading" }
  | { status: "ready"; data: T }
  | { status: "missing" }
  | { status: "error"; error: string };

export type DataContextValue = {
  mode: DataMode;
  /** "api" = live DataSource (local `notary serve`), "static" = replay of published files. */
  source: CatalogOrigin;
  /** The data layer's source. Pages call it for anything beyond the catalog (timelines, approvals, ask). */
  dataSource: DataSource;
  /** Runs the live server reports as still running (no bundle yet). Empty in replay. */
  running: RunEntry[];
  /**
   * True under `?fixtures=1` (development only): the catalog is the fixture runs and pages carry the
   * fixture disclosure. Otherwise the catalog is real runs only; fixture runs are never listed.
   */
  fixtures: boolean;
  /** The visible index entries (real runs, or fixture runs under `?fixtures=1`). Use `runGroups` to present them. */
  runs: BundleIndexEntry[];
  runGroups: RunGroup[];
  /** Every visible verified bundle: one cohort only (real, or fixture under `?fixtures=1`). */
  bundles: RunBundle[];
  /** The selected run, hash-verified. Undefined while loading, on error or when nothing is published. */
  bundle?: RunBundle;
  selectedRunId?: string;
  /** ?run= named a run that is not in the catalog. */
  missingRunId?: string;
  baseline?: RunBundle;
  baselineCandidates: RunBundle[];
  setRun: (runId: string) => void;
  setBaseline: (runId: string) => void;
  loading: boolean;
  error?: string;
  reload: () => void;
  certificates: Loadable<CertificateView>;
  evidence: Loadable<EvidenceEntry[]>;
};

const DataContext = createContext<DataContextValue | null>(null);

export function useData(): DataContextValue {
  const ctx = useContext(DataContext);
  if (!ctx) throw new Error("useData must be used within a DataProvider.");
  return ctx;
}

/** The data world when inside a DataProvider; undefined in isolated renders (tests). */
export function useOptionalData(): DataContextValue | undefined {
  return useContext(DataContext) ?? undefined;
}

type CatalogState =
  | { status: "loading" }
  | { status: "error"; error: string }
  | {
      status: "ready";
      source: CatalogOrigin;
      entries: BundleIndexEntry[];
      running: RunEntry[];
      bundles: RunBundle[];
    };

export function DataProvider({ children }: { children: ReactNode }) {
  const { source: dataSource, mode: sourceMode, ready: sourceReady } = useDataSource();
  const [params, setParams] = useSearchParams();
  const fixtures = fixturesRequested(params);
  const [catalog, setCatalog] = useState<CatalogState>({ status: "loading" });
  const [reloadKey, setReloadKey] = useState(0);
  const [evidence, setEvidence] = useState<Loadable<EvidenceEntry[]>>({
    status: "loading",
  });
  const [certificates, setCertificates] = useState<
    Loadable<CertificateView>
  >({ status: "loading" });

  useEffect(() => {
    if (!sourceReady) return;
    const controller = new AbortController();
    setCatalog({ status: "loading" });
    (async () => {
      // Real runs only, or fixture runs only under ?fixtures=1. Hidden runs are not even fetched.
      const runs = visibleRuns(await dataSource.listRuns(controller.signal), fixtures);
      const entries = finishedEntries(runs).sort(byNewest);
      // Every bundle is schema-checked and hash-verified by the data layer before it arrives here.
      const bundles = (
        await Promise.all(entries.map((e) => dataSource.getRun(e.runId, controller.signal)))
      ).sort(byNewest);
      return {
        source: (sourceMode === "live" ? "api" : "static") as CatalogOrigin,
        entries,
        running: runs.filter((r) => r.state === "running"),
        bundles,
      };
    })()
      .then((world) => {
        if (!controller.signal.aborted)
          setCatalog({ status: "ready", ...world });
      })
      .catch((e: Error) => {
        if (!controller.signal.aborted)
          setCatalog({ status: "error", error: e.message });
      });
    return () => controller.abort();
  }, [reloadKey, dataSource, sourceMode, sourceReady, fixtures]);

  useEffect(() => {
    const controller = new AbortController();
    setEvidence({ status: "loading" });
    loadEvidence(controller.signal)
      .then((entries) => {
        if (!controller.signal.aborted)
          setEvidence(
            entries.length
              ? { status: "ready", data: entries }
              : { status: "missing" },
          );
      })
      .catch((e: Error) => {
        if (!controller.signal.aborted)
          setEvidence({ status: "error", error: e.message });
      });
    return () => controller.abort();
  }, [reloadKey]);

  const requested = params.get("run");
  const ready = catalog.status === "ready" ? catalog : undefined;
  const bundles = useMemo(() => ready?.bundles ?? [], [ready]);
  const entries = useMemo(() => ready?.entries ?? [], [ready]);
  const fallbackId = useMemo(() => defaultRunId(entries), [entries]);
  const bundle = requested
    ? bundles.find((b) => b.runId === requested)
    : bundles.find((b) => b.runId === fallbackId);
  const missingRunId =
    ready && requested && !bundle ? requested : undefined;

  // Keep the selected run in the URL so every page is shareable as-is.
  useEffect(() => {
    if (ready && !requested && fallbackId)
      setParams(
        (p) => {
          const next = new URLSearchParams(p);
          next.set("run", fallbackId);
          return next;
        },
        { replace: true },
      );
  }, [ready, requested, fallbackId, setParams]);

  const certKey = bundle ? `${bundle.sample}:${bundle.runId}` : "";
  useEffect(() => {
    if (!bundle) {
      setCertificates({ status: "missing" });
      return;
    }
    const controller = new AbortController();
    setCertificates({ status: "loading" });
    dataSource
      .certificates(entryOfBundle(bundle), controller.signal)
      .then((world) => {
        if (controller.signal.aborted) return;
        const view = toCertificateView(world);
        setCertificates(view ? { status: "ready", data: view } : { status: "missing" });
      })
      .catch((e: Error) => {
        if (!controller.signal.aborted)
          setCertificates({ status: "error", error: e.message });
      });
    return () => controller.abort();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [certKey, reloadKey, dataSource]);

  const setRun = useCallback(
    (runId: string) =>
      setParams((p) => {
        const next = new URLSearchParams(p);
        next.set("run", runId);
        next.delete("baseline");
        return next;
      }),
    [setParams],
  );
  const setBaseline = useCallback(
    (runId: string) =>
      setParams((p) => {
        const next = new URLSearchParams(p);
        next.set("baseline", runId);
        return next;
      }),
    [setParams],
  );
  const reload = useCallback(() => setReloadKey((v) => v + 1), []);

  const source: CatalogOrigin = ready?.source ?? (sourceMode === "live" ? "api" : "static");
  const value: DataContextValue = {
    mode: resolveDataMode(source, bundle),
    source,
    dataSource,
    fixtures,
    running: ready?.running ?? [],
    runs: entries,
    runGroups: groupRuns(entries, source),
    bundles,
    bundle,
    selectedRunId: bundle?.runId ?? requested ?? fallbackId,
    missingRunId,
    baseline: pickBaseline(bundle, bundles, params.get("baseline")),
    baselineCandidates: baselineCandidates(bundle, bundles),
    setRun,
    setBaseline,
    loading: !sourceReady || catalog.status === "loading",
    error: catalog.status === "error" ? catalog.error : undefined,
    reload,
    certificates,
    evidence,
  };
  return <DataContext.Provider value={value}>{children}</DataContext.Provider>;
}
